using MarathonRMS.DTOs.Events;using MarathonRMS.DTOs.Registrations;using MarathonRMS.WebApp.ApiClients;using MarathonRMS.WebApp.Infrastructure;using Microsoft.AspNetCore.Mvc;
namespace MarathonRMS.WebApp.Pages.Organizer;
public class RefundsModel:BasePageModel
{private readonly EventApiClient _events;private readonly RegistrationApiClient _registrations;public RefundsModel(EventApiClient events,RegistrationApiClient registrations){_events=events;_registrations=registrations;}[BindProperty(SupportsGet=true)]public int? EventId{get;set;}public List<EventSummaryDto> Events{get;private set;}=new();public List<RefundDto> Items{get;private set;}=new();public async Task<IActionResult> OnGetAsync(CancellationToken ct)=>await Load(ct);public async Task<IActionResult> OnPostCompleteAsync(int id,string transactionRef,CancellationToken ct){try{await _registrations.CompleteRefundAsync(id,new(){TransactionRef=transactionRef},ct);StatusMessage="Đã ghi nhận hoàn tiền.";return RedirectToPage(new{EventId});}catch(ApiException ex){return await HandleApiErrorAsync(ex)??await Load(ct);}}public async Task<IActionResult> OnPostRejectAsync(int id,string reason,CancellationToken ct){try{await _registrations.RejectRefundAsync(id,new(){Reason=reason},ct);StatusMessage="Đã từ chối khoản hoàn.";return RedirectToPage(new{EventId});}catch(ApiException ex){return await HandleApiErrorAsync(ex)??await Load(ct);}}private async Task<IActionResult> Load(CancellationToken ct){try{Events=await _events.GetMineAsync(ct);if(EventId is int id)Items=await _registrations.GetRefundsAsync(id,ct);}catch(ApiException ex){return await HandleApiErrorAsync(ex)??Page();}return Page();}}
